import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  spring,
  interpolate,
  Img,
  staticFile,
  Sequence,
} from "remotion";
import { BRAND } from "@/lib/brand";

export const fps = 25;
export const durationInFrames = 350;

const COLORS = {
  bg: BRAND.colors.bg,
  card: BRAND.colors.card,
  border: BRAND.colors.border,
  text: BRAND.colors.text,
  textMuted: BRAND.colors.textMuted,
  textSubtle: BRAND.colors.textSubtle,
  orange: BRAND.colors.orange,
  orangeDeep: BRAND.colors.orangeDeep,
  orangeTint: BRAND.colors.orangeTint,
};

// ============ MOTION HELPERS (inline since this is a single file) ============
const SPRINGS = {
  SNAPPY: { damping: 18, stiffness: 220, mass: 0.7 },
  LIQUID: { damping: 22, stiffness: 110, mass: 1 },
  GENTLE: { damping: 26, stiffness: 90, mass: 1 },
  ELASTIC: { damping: 12, stiffness: 180, mass: 0.8 },
};

const springIn = (
  frame: number,
  fps: number,
  delay: number,
  preset: keyof typeof SPRINGS = "SNAPPY"
) => spring({ frame, fps, delay, config: SPRINGS[preset] });

// Perlin-ish drift using layered sines with a seed hash
const hash = (s: string) => {
  let h = 0;
  for (let i = 0; i < s.length; i++) h = (h * 31 + s.charCodeAt(i)) | 0;
  return Math.abs(h % 1000) / 1000;
};
const ambientDrift = (
  frame: number,
  amplitude: number,
  period: number,
  seed: string
) => {
  const o = hash(seed) * Math.PI * 2;
  return (
    amplitude *
    (Math.sin(frame / period + o) * 0.6 +
      Math.sin(frame / (period * 0.43) + o * 1.7) * 0.4)
  );
};

// ============ DECORATIVE CROSSHAIR ============
