  const textIn = springIn(frame, vfps, 0, "SNAPPY");
  const drift = ambientDrift(frame, 2, 60, "hook");

  return (
    <AbsoluteFill
      style={{
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
      }}
    >
      <div
        style={{
          fontFamily: "'GT Walsheim', Inter, sans-serif",
          fontSize: base * 0.075,
          fontWeight: 700,
          color: COLORS.text,
          letterSpacing: "-0.025em",
          opacity: textIn,
          transform: `translateY(${
            interpolate(textIn, [0, 1], [20, 0]) + drift
          }px)`,
          textAlign: "center",
        }}
      >
        If you've ever...
      </div>
    </AbsoluteFill>
  );
};

