  );
  const phase3 = interpolate(
    frame,
    [112 - fadeWindow, 112, 195 - fadeWindow, 195],
    [0, 1, 1, 0],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );
  const phase4 = interpolate(
    frame,
    [195 - fadeWindow, 195, 283 - fadeWindow, 283],
    [0, 1, 1, 0],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );
  const phase5 = interpolate(
