        </Sequence>
      </AbsoluteFill>

      {/* Phase 3: Small business scrolling */}
      <AbsoluteFill style={{ opacity: phase3 }}>
        <Sequence from={112} durationInFrames={87}>
          <SmallBusinessScene />
